services.command:
sh -c 'mkdir -p /www/lizmap/var/db /www/lizmap/var/config /www/lizmap/var/log /www/lizmap/www && chown -R 1000:1000 /www/lizmap/var /www/lizmap/www && printf "server {
" > /www/lizmap/var/config/default.conf && printf "    listen 80;
" >> /www/lizmap/var/config/default.conf && printf "    server_name _;
" >> /www/lizmap/var/config/default.conf && printf "    root /www/lizmap/www;
" >> /www/lizmap/var/config/default.conf && printf "    index index.php index.html;
" >> /www/lizmap/var/config/default.conf && printf "    client_max_body_size 100M;
" >> /www/lizmap/var/config/default.conf && printf "    fastcgi_read_timeout 300;
" >> /www/lizmap/var/config/default.conf && printf "    location / {
" >> /www/lizmap/var/config/default.conf && printf "        try_files \$uri \$uri/ /index.php\$is_args\$args;
" >> /www/lizmap/var/config/default.conf && printf "    }
" >> /www/lizmap/var/config/default.conf && printf "    location ~ \.php$ {
" >> /www/lizmap/var/config/default.conf && printf "        fastcgi_split_path_info ^(.+\.php)(/.+)$;
" >> /www/lizmap/var/config/default.conf && printf "        fastcgi_pass lizmap:9000;
" >> /www/lizmap/var/config/default.conf && printf "        fastcgi_index index.php;
" >> /www/lizmap/var/config/default.conf && printf "        include fastcgi_params;
" >> /www/lizmap/var/config/default.conf && printf "        fastcgi_param SCRIPT_FILENAME \$document_root\$fastcgi_script_name;
" >> /www/lizmap/var/config/default.conf && printf "        fastcgi_param PATH_INFO \$fastcgi_path_info;
" >> /www/lizmap/var/config/default.conf && printf "    }
" >> /www/lizmap/var/config/default.conf && printf "}
" >> /www/lizmap/var/config/default.conf && chmod 644 /www/lizmap/var/config/default.conf && echo "Config generated, sleeping..." && sleep infinity'
